package com.oms.messaging;
import com.oms.common.tenant.TenantRouting;
import com.ruoyi.common.core.messaging.QueueKind;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.amqp.rabbit.connection.ConnectionFactory;
import org.springframework.amqp.rabbit.listener.SimpleMessageListenerContainer;
import org.springframework.amqp.rabbit.listener.api.ChannelAwareMessageListener;
import org.springframework.amqp.core.AcknowledgeMode;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;
import io.micrometer.core.instrument.*;
import javax.annotation.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static com.oms.messaging.MessageOutbox.*;
/** Every process reconciles its own listener containers. The control service owns desired state. */
@Component @ConditionalOnProperty(name="oms.messaging.enabled",havingValue="true") public class QueueSupervisor {
 @Resource QueueControlClient control;@Resource ConnectionFactory connectionFactory;@Resource MessageOutbox outbox;@Resource TenantRouting tenants;
 @Resource ObjectProvider<MessageRuntime> runtime;@Resource ObjectProvider<MeterRegistry> registry;
 final Map<String,State> states=new ConcurrentHashMap<>();final String instance=System.getenv().getOrDefault("HOSTNAME","local")+":"+token().substring(0,12);
 final ScheduledExecutorService scheduler=Executors.newScheduledThreadPool(3,r->{Thread t=new Thread(r,"mq-control");t.setDaemon(true);return t;});
 final ExecutorService consumers=Executors.newFixedThreadPool(QueueKind.MAX_SERVICE_CONCURRENCY,r->{Thread t=new Thread(r,"mq-consumer");t.setDaemon(true);return t;});
 volatile long configOk;volatile boolean closing;
 static class State {volatile Map<String,Object> policy=Collections.emptyMap();volatile long applied;volatile boolean accepting;volatile String status="STARTING",error="";final AtomicInteger active=new AtomicInteger();SimpleMessageListenerContainer container;volatile Map<String,Object> stats=Collections.emptyMap();}
 @PostConstruct public void start(){for(QueueKind k:QueueKind.service(outbox.service())){State s=new State();s.container=new SimpleMessageListenerContainer(connectionFactory);s.container.setQueueNames(k.queue);s.container.setAcknowledgeMode(AcknowledgeMode.MANUAL);s.container.setAutoStartup(false);s.container.setMissingQueuesFatal(false);s.container.setDefaultRequeueRejected(false);s.container.setForceStop(true);s.container.setShutdownTimeout(45000);s.container.setTaskExecutor(consumers);s.container.setMessageListener((ChannelAwareMessageListener)(message,channel)->runtime.getObject().consume(k.name(),message,channel));s.container.afterPropertiesSet();states.put(k.name(),s);MeterRegistry meters=registry.getIfAvailable();if(meters!=null){Gauge.builder("oms.message.active",s,v->v.active.get()).tag("service",k.service).tag("business_type",k.name()).register(meters);Gauge.builder("oms.message.due",s,v->n(v.stats,"due")).tag("service",k.service).tag("business_type",k.name()).register(meters);Gauge.builder("oms.message.oldest.due.seconds",s,v->n(v.stats,"oldest_due_sec")).tag("service",k.service).tag("business_type",k.name()).register(meters);}}
  scheduler.scheduleWithFixedDelay(()->safe(this::refresh),1,5,TimeUnit.SECONDS);scheduler.scheduleWithFixedDelay(()->safe(this::heartbeat),2,5,TimeUnit.SECONDS);scheduler.scheduleWithFixedDelay(()->safe(this::statistics),10,30,TimeUnit.SECONDS);
 }
 void safe(Runnable action){if(closing)return;try{action.run();}catch(Exception e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Queue management operation unavailable service={}",outbox.service());}finally{TenantRouting.clearContext();}}
 Map<String,Object> identity(){Map<String,Object> r=new LinkedHashMap<>();r.put("service",outbox.service());r.put("instance",instance);return r;}
 void refresh(){R<List<Map<String,Object>>> result=control.snapshot(identity(),SecurityConstants.INNER);require(result!=null&&R.isSuccess(result)&&result.getData()!=null,"队列控制配置不可用");List<Map<String,Object>> policies=result.getData();require(policies.size()==states.size(),"队列控制配置不完整");int total=0;Set<String> seen=new HashSet<>();for(Map<String,Object> p:policies){QueueKind k=QueueKind.of(s(p,"business_type"));require(k.service.equals(outbox.service())&&seen.add(k.name())&&n(p,"revision")>0&&n(p,"concurrency")>=1&&n(p,"concurrency")<=8&&n(p,"prefetch")>=1&&n(p,"prefetch")<=50&&Arrays.asList("RUNNING","PAUSED").contains(s(p,"desired_mode")),"队列控制配置无效");total+=n(p,"concurrency");}require(total<=QueueKind.maxConcurrency(outbox.service()),"消费资源配置超过实例上限");configOk=System.currentTimeMillis();for(Map<String,Object> p:policies){State s=states.get(s(p,"business_type"));apply(s,p);}configOk=System.currentTimeMillis();}
 void apply(State s,Map<String,Object> p){if(closing)return;if(s.applied==n(p,"revision")){s.error="";return;}s.accepting=false;s.status="PAUSED".equals(s(p,"desired_mode"))?"DRAINING":"APPLYING";s.policy=Collections.unmodifiableMap(new LinkedHashMap<>(p));try{if(s.container.isRunning())s.container.stop();s.container.setConcurrentConsumers((int)n(p,"concurrency"));s.container.setPrefetchCount((int)n(p,"prefetch"));if("RUNNING".equals(s(p,"desired_mode")))s.container.start();s.applied=n(p,"revision");s.error="";s.accepting="RUNNING".equals(s(p,"desired_mode"));s.status=s.accepting?"RUNNING":"PAUSED";}catch(RuntimeException e){s.status="ERROR";s.error="消费容器配置未生效，系统将重试";}}
 public Map<String,Object> policy(String type){State s=states.get(type);return s==null?Collections.emptyMap():s.policy;}
 public boolean enabled(String type){State s=states.get(type);return !closing&&s!=null&&s.accepting&&System.currentTimeMillis()-configOk<20000&&s.applied==n(s.policy,"revision");}
 /** Both MQ and compensation must obtain the same local admission. In-flight work may finish. */
 public Permit enter(String type){State s=states.get(type);if(s==null)return null;synchronized(s){if(!enabled(type)||s.active.get()>=n(s.policy,"concurrency"))return null;s.active.incrementAndGet();return new Permit(s);}}
 public static class Permit implements AutoCloseable {private State state;Permit(State state){this.state=state;}public void close(){if(state!=null){state.active.decrementAndGet();state=null;}}}
 public boolean rate(String type,List<String> keys){if(keys.isEmpty())return true;try{Map<String,Object> body=identity();body.put("business_type",type);body.put("keys",keys);R<Boolean> r=control.rate(body,SecurityConstants.INNER);return r!=null&&R.isSuccess(r)&&Boolean.TRUE.equals(r.getData());}catch(RuntimeException e){return false;}}
 void heartbeat(){List<Map<String,Object>> rows=new ArrayList<>();for(Map.Entry<String,State> entry:states.entrySet()){State s=entry.getValue();Map<String,Object> r=new LinkedHashMap<>();r.put("business_type",entry.getKey());r.put("applied_version",s.applied);int count=s.container.getActiveConsumerCount();r.put("actual_consumers",count);r.put("active_work",s.active.get());String status=s.status;if("PAUSED".equals(status)&&s.active.get()>0)status="DRAINING";if("RUNNING".equals(status)&&count!=n(s.policy,"concurrency"))status=count==0?"CONNECTING":"APPLYING";if(closing&&s.active.get()==0&&count==0)status="STOPPED";else if(System.currentTimeMillis()-configOk>=20000){status="ERROR";s.error="控制配置已过期，暂停领取新任务";}r.put("state",status);r.put("last_error",s.error);r.put("stats",s.stats);rows.add(r);}Map<String,Object> body=identity();body.put("queues",rows);control.heartbeat(body,SecurityConstants.INNER);}
 void statistics(){Map<String,Map<String,Object>> totals=new HashMap<>();for(String type:states.keySet()){Map<String,Object> r=new LinkedHashMap<>();for(String field:Arrays.asList("outstanding","due","pending_publish","oldest_due_sec","recent_failed","recent_completed"))r.put(field,0L);totals.put(type,r);}boolean complete=true;Set<String> companies="order".equals(outbox.service())?tenants.continuingCompanies():tenants.companies();for(String c:companies)try(TenantRouting.Binding ignored="order".equals(outbox.service())?tenants.openForContinuation(c):tenants.open(c)){for(String type:states.keySet()){Map<String,Object> r=outbox.db.queryForMap("SELECT COALESCE(SUM(process_state IN ('PENDING','WAITING','PROCESSING')),0) outstanding,COALESCE(SUM(process_state IN ('PENDING','WAITING','PROCESSING') AND next_process_at<=NOW(3) AND (work_until IS NULL OR work_until<NOW(3))),0) due,COALESCE(SUM(process_state IN ('PENDING','WAITING','PROCESSING') AND publish_state IN ('PENDING','UNCERTAIN')),0) pending_publish,COALESCE(MAX(IF(process_state IN ('PENDING','WAITING','PROCESSING') AND (work_until IS NULL OR work_until<NOW(3)),GREATEST(0,TIMESTAMPDIFF(SECOND,next_process_at,NOW(3))),0)),0) oldest_due_sec FROM oms_message_outbox WHERE company_code=? AND service_code=? AND message_type=? AND process_state IN ('PENDING','WAITING','PROCESSING')",c,outbox.service(),type);r.putAll(outbox.db.queryForMap("SELECT COALESCE(SUM(process_state='FAILED'),0) recent_failed,COUNT(*) recent_completed FROM oms_message_outbox WHERE company_code=? AND service_code=? AND message_type=? AND completed_at>=DATE_SUB(NOW(),INTERVAL 5 MINUTE)",c,outbox.service(),type));Map<String,Object> sum=totals.get(type);for(String key:r.keySet())sum.put(key,key.equals("oldest_due_sec")?Math.max(n(sum,key),n(r,key)):n(sum,key)+n(r,key));}}catch(RuntimeException e){complete=false;}if(complete)for(String type:totals.keySet()){totals.get(type).put("sampled_ms",System.currentTimeMillis());states.get(type).stats=totals.get(type);}}
 public void record(String type,String result,String mode,long nanos){MeterRegistry m=registry.getIfAvailable();if(m!=null){m.counter("oms.message.process", "service",outbox.service(),"business_type",type,"result",result,"mode",mode).increment();io.micrometer.core.instrument.Timer.builder("oms.message.processing").tags("service",outbox.service(),"business_type",type).publishPercentileHistogram().register(m).record(nanos,TimeUnit.NANOSECONDS);}}
 @PreDestroy public void close(){closing=true;states.values().forEach(s->s.accepting=false);scheduler.shutdownNow();for(State s:states.values())s.container.stop();try{heartbeat();}catch(RuntimeException ignored){}consumers.shutdown();}
}
